/* ===== alerts.js ===== */
/* games/alerts.js  |  PF v1.4.3 | RAPID RESPONSE: breaking-moment mobilization.
   When news breaks, speed wins. Active alerts name the moment; creators
   respond with posters and log the response for +25 XP.
   KILL: ?pf_off=alerts  or  localStorage pf_disabled_v1='["alerts"]' */
(function () {
  'use strict';
  var PF = window.PF;
  if (!PF || PF.skip("alerts")) { return; }
  PF.holder().insertAdjacentHTML('beforeend', `<template id="pf-ov-alerts">
<div class="fe-block pf-override-block" id="pf-alerts">
<style>
/* QUIET COLLAPSE (2026-10-05, display-only): when alert_list is empty the
   widget shrinks to this slim strip instead of a full section. .pf-quiet is
   toggled by the inner script; the strip stays visible as the mobilization
   anchor, so expanding on an alert never yanks the page. */
#pf-alerts .pf-quietstrip{display:none;align-items:center;justify-content:center;gap:8px;
  font-family:Arial,sans-serif;font-size:12px;letter-spacing:1px;color:#9c8f78;
  padding:9px 12px;border:1px solid #2c2c2c;border-radius:6px;background:#0d0d0d;
  max-width:680px;margin:0 auto;text-align:center}
#pf-alerts .pf-quietstrip b{color:#c1121f;letter-spacing:2px}
#pf-alerts.pf-quiet #pf-alerts-body{display:none}
#pf-alerts.pf-quiet .pf-quietstrip{display:flex}
#pf-alerts.pf-quiet .pf-next{display:none}
/* mid-session alert arrival: flash + toast, impossible to miss */
#pf-alerts.pf-flash{animation:pfAlFlash 1.4s ease-in-out 3}
@keyframes pfAlFlash{0%,100%{box-shadow:0 0 0 0 rgba(193,18,31,0)}
  50%{box-shadow:0 0 6px 3px rgba(193,18,31,.85)}}
</style>
<div class="pf-quietstrip">&#9889; <b>RAPID RESPONSE</b><span>&mdash; the wire is quiet. We move in minutes when it breaks.</span></div>
<div id="pf-alerts-body">
<h2>Rapid Response</h2>
<div class="c-tag">News breaks. We move in minutes, not days.</div>
<div id="xAlerts"><div class="c-load">Scanning the wire&hellip;</div></div>
</div>
</div>
<script>
(function(){
var BACKEND=window.PF_BACKEND_URL;
function esc(s){ return String(s==null?"":s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;"); }
function ident(){ var cs="",dev=""; try{ cs=window.PFCallsign?window.PFCallsign():""; }catch(e){} try{ dev=window.PFDeviceId?window.PFDeviceId():""; }catch(e){} return {callsign:cs,device:dev}; }
function toast(m){ try{ if(window.PF&&PF.toast){ PF.toast(m); return; } }catch(e){}
  try{ var t=document.createElement("div"); t.textContent=m;
  t.style.cssText="position:fixed;left:50%;top:16%;transform:translateX(-50%);background:#c1121f;color:#fff;font:bold 15px monospace;padding:12px 22px;border:2px solid #fff;z-index:99999";
  document.body.appendChild(t); setTimeout(function(){ t.remove(); },2800); }catch(e2){} }
function api(action,params,cb){
  if(!BACKEND){ cb(null); return; }
  var fn="pfAlCb"+Math.floor(Math.random()*1e9);
  var s=document.createElement("script"), done=false;
  function finish(j){ if(done)return; done=true; try{delete window[fn];}catch(e){}
    if(s.parentNode)s.parentNode.removeChild(s); cb(j); }
  window[fn]=function(j){ finish(j); };
  s.onerror=function(){ finish(null); };
  var q="?action="+encodeURIComponent(action);
  for(var k in params){ if(params[k]!=null&&params[k]!=="") q+="&"+encodeURIComponent(k)+"="+encodeURIComponent(params[k]); }
  q+="&callback="+fn; s.src=BACKEND+q; document.head.appendChild(s);
  setTimeout(function(){ finish(null); },12000);
}
function post(cAction,params,cb){
  var body=Object.assign({type:"alert",al_action:cAction},params);
  if(window.PF&&PF.authPost){ PF.authPost(BACKEND,body,cb); return; }
  var bodyStr=JSON.stringify(body);
  function done(j){ try{ cb(j||{ok:false,err:"Network error."}); }catch(e){} }
  try{
    /* L2 (2026-10-03): 15s abort on the no-authPost fallback (was: hung POST spins forever). */
    var _po=(function(){ var o={method:"POST",headers:{"Content-Type":"application/json"},body:bodyStr},c=null,t=null;
      try{ if(window.AbortController){ c=new AbortController(); o.signal=c.signal;
        t=setTimeout(function(){ try{ c.abort(); }catch(e){} },15000); } }catch(e){}
      o._pfClear=function(){ if(t){ try{ clearTimeout(t); }catch(e){} } }; return o; })();
    fetch(BACKEND,_po)
      .then(function(r){ return r.json(); })
      .then(function(j){ _po._pfClear(); done(j); })
      .catch(function(){ _po._pfClear(); done(null); });
  }catch(e){ done(null); }
}
function fmtTs(t){
  try{
    var ms=Number(t); if(ms<1e12) ms=ms*1000;
    var d=new Date(ms); if(isNaN(d.getTime())) return "";
    var mo=["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
    var h=d.getHours(), ap=h>=12?"pm":"am"; h=h%12; if(h===0)h=12;
    return mo[d.getMonth()]+" "+d.getDate()+", "+h+":"+("0"+d.getMinutes()).slice(-2)+ap;
  }catch(e){ return ""; }
}
/* QUIET COLLAPSE state (2026-10-05, display-only). render() is the single
   choke point for alert_list — initial load, the Refresh button, and the
   3-minute poll all flow through it, so an alert that fires while the page
   is open re-expands here automatically. A failed fetch keeps CURRENT
   behavior (visible, honest pane) — never hide content on an error. */
var quietOn=false;
function alBlock(){ try{ return document.getElementById("pf-alerts"); }catch(e){ return null; } }
function setQuiet(on){
  quietOn=!!on;
  try{ var b=alBlock(); if(b){ if(on) b.classList.add("pf-quiet"); else b.classList.remove("pf-quiet"); } }catch(e){}
}
function load(){
  var el=document.getElementById("xAlerts"); if(!el) return;
  api("alert_list",{},function(j){ render(j); });
  setTimeout(function(){ if(el.innerHTML.indexOf("c-load")>=0) render(null); },15000);
}
function render(j){
  var el=document.getElementById("xAlerts"); if(!el) return;
  var id=ident(), h="";
  var ok=!!(j&&j.ok);
  var alerts=ok?(j.alerts||[]):[];
  if(!ok){
    /* FAIL SOFT: exactly as today — visible section, honest quiet pane. */
    setQuiet(false);
    h+='<div class="x-pane"><div class="x-note">No active alerts. The wire is quiet &mdash; for now. When a moment breaks, it lands here first. <a href="/create?tab=bounties" style="color:#c1121f;font-weight:700;text-decoration:none">HIT THE OPEN BOUNTIES &#8594;</a></div></div>';
    h+='<div style="margin-top:10px"><button class="c-btn" id="alRetry">Refresh</button></div>';
    el.innerHTML=h;
    var rb0=document.getElementById("alRetry");
    if(rb0) rb0.onclick=function(){ el.innerHTML='<div class="c-load">Scanning the wire&hellip;</div>'; load(); };
    return;
  }
  if(!alerts.length){
    /* Quiet: collapse to the slim strip. The 3-minute poll re-checks. */
    setQuiet(true);
    el.innerHTML="";
    return;
  }
  var wasQuiet=quietOn;
  setQuiet(false);
  for(var i=0;i<alerts.length;i++){
    var a=alerts[i];
    h+='<div class="x-pane al-pane">'
      +'<div class="al-flash">&#9889; ACTIVE ALERT</div>'
      +'<h4>'+esc(a.headline)+'</h4>'
      +'<div class="x-note">'+esc(a.context||"")+'</div>'
      +'<div class="al-meta">'+esc(fmtTs(a.created_at))+' &bull; '+(Number(a.response_count)||0)+' responses</div>'
      +'<div class="al-btns">';
    if(id.callsign){
      h+='<button class="c-btn" data-al-forge="'+esc(a.id)+'" data-al-tpl="'+esc(a.template_id||"")+'">RESPOND: MAKE A POSTER</button>'
        +'<button class="c-btn c-btn2" data-al-done="'+esc(a.id)+'">I RESPONDED</button>'
        /* QW-13 (2026-10-05): alert energy routes to open bounties — zero new
           XP, zero new endpoints, plain anchor in the .al-btns row. */
        +'<a class="c-btn c-btn2" href="/create?tab=bounties" style="text-decoration:none;display:inline-block">OPEN BOUNTIES &#8594;</a>';
    } else {
      h+='<div class="x-note">Claim a callsign in Enlistment Ranks to respond.</div>';
    }
    h+='</div><div class="c-err" id="alErr'+esc(a.id)+'"></div></div>';
  }
  h+='<div style="margin-top:10px"><button class="c-btn" id="alRetry">Refresh</button></div>';
  el.innerHTML=h;
  /* wire: open poster forge with template context */
  var fbs=el.querySelectorAll("button[data-al-forge]");
  for(var f=0;f<fbs.length;f++){
    (function(btn){
      btn.onclick=function(){
        try{
          document.dispatchEvent(new CustomEvent("pf-alert-forge",{detail:{alert:btn.getAttribute("data-al-forge"),template:btn.getAttribute("data-al-tpl")}}));
        }catch(e){}
        toast("Open Poster Forge and answer the alert.");
        var pf=document.getElementById("pf-poster");
        if(pf){ try{ pf.scrollIntoView({behavior:"smooth",block:"start"}); }catch(e2){} }
      };
    })(fbs[f]);
  }
  /* wire: log response */
  var dbs=el.querySelectorAll("button[data-al-done]");
  for(var d=0;d<dbs.length;d++){
    (function(btn){
      btn.onclick=function(){
        var aid=btn.getAttribute("data-al-done");
        var cid=window.prompt("Paste the content ID of the poster you made for this alert:");
        if(!cid) return;
        btn.disabled=true;
        post("alert_respond",{callsign:id.callsign,device:id.device,alert_id:aid,content_id:cid.trim()},function(j){
          if(!j||!j.ok){
            var e=document.getElementById("alErr"+aid);
            if(e) e.textContent=PF.errCopy(j,"Response failed.");
            btn.disabled=false; return;
          }
          toast(j.dup?"Already logged. Stay sharp.":"+25 XP — rapid response logged.");
          load();
        });
      };
    })(dbs[d]);
  }
  var rb=document.getElementById("alRetry");
  if(rb) rb.onclick=function(){ el.innerHTML='<div class="c-load">Scanning the wire&hellip;</div>'; load(); };
  if(wasQuiet){
    /* An alert fired while the page was open: impossible to miss. */
    try{
      var b=alBlock();
      if(b){
        b.classList.remove("pf-flash"); void b.offsetWidth; b.classList.add("pf-flash");
        setTimeout(function(){ try{ b.classList.remove("pf-flash"); }catch(e){} },4600);
        try{ b.scrollIntoView({behavior:"smooth",block:"center"}); }catch(e2){}
      }
    }catch(e){}
    toast("\u26A1 ACTIVE ALERT \u2014 rapid response needed. Move now.");
  }
}
load();
setInterval(function(){ try{ if(window.PF&&PF.hidden&&PF.hidden()) return; }catch(e){} load(); },180000);
})();
</scr`+`ipt>
</div>
</template>`);
})();

;

/* ===== fb-missions.js ===== */
/* games/fb-missions.js  |  PF v1.4.3 | FB GROUP MISSIONS.
   Engagement build D, item #8 (gates: Economy SIGNED, Brand PROCESS GATE).
   Missions are POSTED MANUALLY to the 84K-member Facebook group by Shane or
   a group admin — facebook-cli has no group-post write, so this module does
   NOT post anything. It builds the on-site half: live mission cards, the
   proof check-in form, and check-in status.
   Flow: see the mission card in the group -> post your proof (a post or
   comment) in the group with the mission code-word -> paste the proof
   permalink below -> verification runs (off-worker, facebook-cli reads) ->
   verified: +5 XP through the existing create_share: leg (2/day, 30-day
   proof dedup). Rejected: 0 XP.
   Mounts: PF.holder() (homepage ORDER entry). Fail-soft: no missions,
   backend down -> the section hides.
   KILL: ?pf_off=fb-missions  or  localStorage pf_disabled_v1='["fb-missions"]' */
(function () {
  'use strict';
  var PF = window.PF;
  if (!PF || PF.skip("fb-missions")) { return; }
  PF.holder().insertAdjacentHTML('beforeend', `<template id="pf-ov-fbmissions">
<style>
#pf-fbmissions .fm-card{background:#0d0d0d;border:1px solid #2a2a2a;border-radius:10px;padding:16px;margin-bottom:12px}
#pf-fbmissions .fm-k{font-size:11px;letter-spacing:3px;color:#e8b923;font-weight:700}
#pf-fbmissions .fm-b{font-size:15px;color:#f5ead6;margin:8px 0;line-height:1.55}
#pf-fbmissions .fm-meta{font-size:12px;color:#8a7f68;margin:6px 0}
#pf-fbmissions .fm-row{display:flex;gap:8px;margin-top:10px;flex-wrap:wrap}
#pf-fbmissions .fm-in{flex:1;min-width:200px;background:#1a1a1a;border:1px solid #3a3a3a;color:#f5ead6;border-radius:6px;padding:10px 12px;font-size:14px}
#pf-fbmissions .fm-btn{background:#c1121f;color:#fff;border:0;border-radius:6px;padding:10px 18px;font-weight:900;letter-spacing:1px;cursor:pointer;font-size:13px}
#pf-fbmissions .fm-btn:disabled{opacity:.45;cursor:default}
#pf-fbmissions .fm-btn.ghost{background:#1a1a1a;border:1px solid #3a3a3a;color:#f5ead6;text-decoration:none;display:inline-block}
#pf-fbmissions .fm-note{font-size:12px;color:#8a7f68;margin-top:8px;line-height:1.5}
#pf-fbmissions .fm-st{font-size:13px;font-weight:700;margin-top:8px}
#pf-fbmissions .fm-st.pending{color:#e8b923}
#pf-fbmissions .fm-st.verified{color:#7fc97f}
#pf-fbmissions .fm-st.rejected{color:#e88}
#pf-fbmissions .fm-mine{margin-top:14px;border-top:1px dashed #3a3a3a;padding-top:10px}
#pf-fbmissions .fm-mi{font-size:13px;color:#c9bfa8;padding:6px 0;border-bottom:1px solid #1a1a1a}
</style>
<div class="fe-block pf-override-block pf-silo" id="pf-fbmissions">
<h2>Group Missions</h2>
<div class="c-tag">Missions drop in the Facebook group. Post your proof there, check in here, get paid.</div>
<div id="xFbMissions"><div class="c-load">Loading missions&hellip;</div></div>
</div>
<script>
(function(){
if(window.pfFbMissionsDone) return; window.pfFbMissionsDone=true;
var PF=window.PF||{skip:function(){return false;},error:function(){},toast:function(){}};
if(PF.skip("fb-missions")) return;
function esc(s){ return String(s==null?"":s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;"); }
function okURL(u){ var s=String(u==null?"":u).trim(); return /^(https?:)[/][/]/i.test(s)?s:""; }
function ident(){ var cs="",dev=""; try{ cs=window.PFCallsign?window.PFCallsign():""; }catch(e){} try{ dev=window.PFDeviceId?window.PFDeviceId():""; }catch(e){} return {callsign:cs,device:dev}; }
function post(action, params, cb){
  var done=function(j){ try{ cb(j||{ok:false,err:"Network error."}); }catch(e){} };
  try{
    if(window.PF && PF.postAction){
      var p={}; for(var k in params) p[k]=params[k];
      var id=ident(); if(id.callsign) p.callsign=id.callsign; if(id.device) p.device=id.device;
      PF.postAction('readcreate','rc_action',action,p,done); return;
    }
  }catch(e){}
  done(null);
}
var box=document.getElementById("xFbMissions");
function hide(){ try{ var root=document.getElementById("pf-fbmissions"); var sec=root&&root.closest?root.closest("section"):null; (sec||root).style.display="none"; }catch(e){} }
function fmtEnd(ts){
  try{
    var d=new Date(Number(ts));
    return d.toLocaleDateString("en-US",{month:"short",day:"numeric"})+" "+
           d.toLocaleTimeString("en-US",{hour:"numeric",minute:"2-digit"});
  }catch(e){ return ""; }
}
function render(missions, mine){
  var h="";
  if(!missions.length && !mine.length){ hide(); return; }
  for(var i=0;i<missions.length;i++){
    var m=missions[i];
    h+='<div class="fm-card" data-fm="'+esc(m.id)+'">';
    h+='<div class="fm-k">GROUP MISSION &middot; +5 XP</div>';
    h+='<div class="fm-b">'+esc(m.brief)+'</div>';
    h+='<div class="fm-meta">Closes '+esc(fmtEnd(m.window_end))+' &middot; proof: a post or comment in the group with the mission code-word</div>';
    var gl=okURL(m.group_permalink);
    if(gl) h+='<a class="fm-btn ghost" href="'+esc(gl)+'" target="_blank" rel="noopener">VIEW MISSION CARD IN THE GROUP</a>';
    var id=ident();
    if(id.callsign){
      h+='<div class="fm-row"><input class="fm-in" data-fm-proof placeholder="Paste your proof permalink (facebook.com…)" autocomplete="off">';
      h+='<button class="fm-btn" data-fm-check>CHECK IN</button></div>';
      h+='<div class="fm-note">One check-in per mission. Verification runs after you post — no XP until your proof passes.</div>';
      h+='<div class="fm-st" data-fm-status></div>';
    }else{
      h+='<div class="fm-note">Claim a callsign to check in for group missions.</div>';
    }
    h+='</div>';
  }
  if(mine.length){
    h+='<div class="fm-mine"><div class="fm-k">YOUR CHECK-INS</div>';
    for(var k=0;k<mine.length;k++){
      var c=mine[k];
      h+='<div class="fm-mi"><b>'+esc(c.mission_id)+'</b> — <span class="fm-st '+esc(c.status)+'">'+esc(c.status).toUpperCase()+'</span>'+
         (c.reason?' <span style="color:#8a7f68">('+esc(c.reason)+')</span>':'')+'</div>';
    }
    h+='</div>';
  }
  box.innerHTML=h;
  var btns=box.querySelectorAll("[data-fm-check]");
  for(var b=0;b<btns.length;b++){
    (function(btn){
      btn.addEventListener("click", function(){
        var card=btn.closest("[data-fm]");
        var mid=card?card.getAttribute("data-fm"):"";
        var inp=card?card.querySelector("[data-fm-proof]"):null;
        var st=card?card.querySelector("[data-fm-status]"):null;
        var url=inp?inp.value.trim():"";
        if(!url||!/facebook[.]com/i.test(url)){ if(st){ st.className="fm-st rejected"; st.textContent="Paste a facebook.com permalink to your proof."; } return; }
        btn.disabled=true;
        post("fbmission_checkin",{mission_id:mid,proof_url:url},function(j){
          if(j&&j.ok){
            if(st){ st.className="fm-st pending"; st.textContent=j.dup?"Already submitted — still pending verification.":"Proof received — pending verification. Check back after the group post is checked."; }
            if(window.PF&&PF.toast) PF.toast("PROOF LOGGED — PENDING VERIFICATION");
          }else{
            if(st){ st.className="fm-st rejected"; st.textContent="Check-in failed: "+((j&&j.err)||"error"); }
            btn.disabled=false;
          }
        });
      });
    })(btns[b]);
  }
}
function boot(){
  var id=ident();
  post("fbmission_list",{},function(l){
    var missions=(l&&l.ok&&l.missions)||[];
    if(id.callsign){
      post("fbmission_mine",{},function(mn){
        render(missions,(mn&&mn.ok&&mn.checkins)||[]);
      });
    }else render(missions,[]);
  });
  setTimeout(function(){ if(box&&box.querySelector(".c-load")) hide(); },12000);
}
try{ boot(); }catch(e){ hide(); }
})();
</script>
</template>
`);
})();

